import { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

export default function Cadastrar() {
  const [form, setForm] = useState({
    nome: "",
    idade: "",
    rua: "",
    bairro: "",
    estado: "",
    biografia: "",
    foto: null,
  });

  const navigate = useNavigate();

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e) => {
    setForm((prev) => ({ ...prev, foto: e.target.files[0] }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const formData = new FormData();
    for (const key in form) {
      formData.append(key, form[key]);
    }

    try {
      await axios.post("http://localhost:3001/usuarios", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      alert("Usuário cadastrado com sucesso!");
      navigate("/usuarios");
    } catch (erro) {
      console.error("Erro ao cadastrar:", erro);
      alert("Erro ao cadastrar usuário.");
    }
  };

  return (
    <div className="container mt-4">
      <h2 className="text-center mb-4">Cadastrar Novo Usuário</h2>
      <form onSubmit={handleSubmit} className="row g-3">
        <div className="col-md-6">
          <input type="text" name="nome" className="form-control" placeholder="Nome completo" value={form.nome} onChange={handleChange} required />
        </div>
        <div className="col-md-6">
          <input type="number" name="idade" className="form-control" placeholder="Idade" value={form.idade} onChange={handleChange} required />
        </div>
        <div className="col-md-6">
          <input type="text" name="rua" className="form-control" placeholder="Rua" value={form.rua} onChange={handleChange} required />
        </div>
        <div className="col-md-6">
          <input type="text" name="bairro" className="form-control" placeholder="Bairro" value={form.bairro} onChange={handleChange} required />
        </div>
        <div className="col-md-6">
          <input type="text" name="estado" className="form-control" placeholder="Estado" value={form.estado} onChange={handleChange} required />
        </div>
        <div className="col-12">
          <textarea name="biografia" className="form-control" placeholder="Biografia" rows="3" value={form.biografia} onChange={handleChange}></textarea>
        </div>
        <div className="col-12">
          <input type="file" name="foto" className="form-control" accept="image/*" onChange={handleFileChange} required />
        </div>
        <div className="col-12 text-center">
          <button type="submit" className="btn btn-success">Cadastrar</button>
        </div>
      </form>
    </div>
  );
}
